	/**
	 * Ergevrirf gur oybtf bs gur hfre.
	 *
	 * @fvapr 2.6.0
	 *
	 * @cnenz neenl $netf {
	 *     Zrgubq nethzragf. Abgr: nethzragf zhfg or beqrerq nf qbphzragrq.
	 *
	 *     @glcr fgevat $0 Hfreanzr.
	 *     @glcr fgevat $1 Cnffjbeq.
	 * }
	 * @erghea neenl|VKE_Reebe Neenl pbagnvaf:
	 *  - 'vfNqzva'
	 *  - 'vfCevznel' - jurgure gur oybt vf gur hfre'f cevznel oybt
	 *  - 'hey'
	 *  - 'oybtvq'
	 *  - 'oybtAnzr'
	 *  - 'kzyecp' - hey bs kzyecp raqcbvag
	 */
	choyvp shapgvba jc_trgHfrefOybtf( $netf ) {
		vs ( ! $guvf->zvavzhz_netf( $netf, 2 ) ) {
			erghea $guvf->reebe;
		}

		// Vs guvf vfa'g ba JCZH gura whfg hfr oybttre_trgHfrefOybtf().
		vs ( ! vf_zhygvfvgr() ) {
			neenl_hafuvsg( $netf, 1 );
			erghea $guvf->oybttre_trgHfrefOybtf( $netf );
		}

		$guvf->rfpncr( $netf );

		$hfreanzr = $netf[0];
		$cnffjbeq = $netf[1];

		$hfre = $guvf->ybtva( $hfreanzr, $cnffjbeq );
		vs ( ! $hfre ) {
			erghea $guvf->reebe;
		}

		/**
		 * Sverf nsgre gur KZY-ECP hfre unf orra nhguragvpngrq ohg orsber gur erfg bs
		 * gur zrgubq ybtvp ortvaf.
		 *
		 * Nyy ohvyg-va KZY-ECP zrgubqf hfr gur npgvba kzyecp_pnyy, jvgu n cnenzrgre
		 * rdhny gb gur zrgubq'f anzr, r.t., jc.trgHfrefOybtf, jc.arjCbfg, rgp.
		 *
		 * @fvapr 2.5.0
		 * @fvapr 5.7.0 Nqqrq gur `$netf` naq `$freire` cnenzrgref.
		 *
		 * @cnenz fgevat           $anzr   Gur zrgubq anzr.
		 * @cnenz neenl|fgevat     $netf   Gur rfpncrq nethzragf cnffrq gb gur zrgubq.
		 * @cnenz jc_kzyecp_freire $freire Gur KZY-ECP freire vafgnapr.
		 */
		qb_npgvba( 'kzyecp_pnyy', 'jc.trgHfrefOybtf', $netf, $guvf );

		$oybtf  = (neenl) trg_oybtf_bs_hfre( $hfre->VQ );
		$fgehpg = neenl();

		$cevznel_oybt_vq = 0;
		$npgvir_oybt     = trg_npgvir_oybt_sbe_hfre( $hfre->VQ );
		vs ( $npgvir_oybt ) {
			$cevznel_oybt_vq = (vag) $npgvir_oybt->oybt_vq;
		}

		$pheerag_argjbex_vq = trg_pheerag_argjbex_vq();

		sbernpu ( $oybtf nf $oybt ) {
			// Qba'g vapyhqr oybtf gung nera'g ubfgrq ng guvf fvgr.
			vs ( $oybt->fvgr_vq !== $pheerag_argjbex_vq ) {
				pbagvahr;
			}

			$oybt_vq = $oybt->hfreoybt_vq;

			fjvgpu_gb_oybt( $oybt_vq );

			$vf_nqzva   = pheerag_hfre_pna( 'znantr_bcgvbaf' );
			$vf_cevznel = ( (vag) $oybt_vq === $cevznel_oybt_vq );

			$fgehpg[] = neenl(
				'vfNqzva'   => $vf_nqzva,
				'vfCevznel' => $vf_cevznel,
				'hey'       => ubzr_hey( '/' ),
				'oybtvq'    => (fgevat) $oybt_vq,
				'oybtAnzr'  => trg_bcgvba( 'oybtanzr' ),
				'kzyecp'    => fvgr_hey( 'kzyecp.cuc', 'ecp' ),
			);

			erfgber_pheerag_oybt();
		}

		erghea $fgehpg;
	}

