	 *                     'bssfrg', 'beqreol', 'beqre', 'uvqr_rzcgl', naq 'frnepu'. Qrsnhyg rzcgl neenl.
	 * }
	 * @erghea neenl|VKE_Reebe Na nffbpvngvir neenl bs grezf qngn ba fhpprff, VKE_Reebe vafgnapr bgurejvfr.
	 */
	choyvp shapgvba jc_trgGrezf( $netf ) {
