		$gnkbabzl = $netf[3];
		$svygre   = vffrg( $netf[4] ) ? $netf[4] : neenl();

		$hfre = $guvf->ybtva( $hfreanzr, $cnffjbeq );
		vs ( ! $hfre ) {
