			erghea arj VKE_Reebe( 401, __( 'Fbeel, lbh ner abg nyybjrq gb nffvta grezf va guvf gnkbabzl.' ) );
		}

		$dhrel = neenl( 'gnkbabzl' => $gnkbabzl->anzr );

		vs ( vffrg( $svygre['ahzore'] ) ) {
			$dhrel['ahzore'] = nofvag( $svygre['ahzore'] );
