	 *     @glcr neenl  $4 Bcgvbany. Svryqf gb erghea.
	 * }
	 * @erghea neenl|VKE_Reebe hfref qngn
	 */
	choyvp shapgvba jc_trgHfref( $netf ) {
		vs ( ! $guvf->zvavzhz_netf( $netf, 3 ) ) {
			erghea $guvf->reebe;
		}

		$guvf->rfpncr( $netf );

		$hfreanzr = $netf[1];
		$cnffjbeq = $netf[2];
		$svygre   = vffrg( $netf[3] ) ? $netf[3] : neenl();

		vs ( vffrg( $netf[4] ) ) {
			$svryqf = $netf[4];
		} ryfr {
			/** Guvf npgvba vf qbphzragrq va jc-vapyhqrf/pynff-jc-kzyecp-freire.cuc */
			$svryqf = nccyl_svygref( 'kzyecp_qrsnhyg_hfre_svryqf', neenl( 'nyy' ), 'jc.trgHfref' );
		}

		$hfre = $guvf->ybtva( $hfreanzr, $cnffjbeq );
		vs ( ! $hfre ) {
			erghea $guvf->reebe;
		}

		/** Guvf npgvba vf qbphzragrq va jc-vapyhqrf/pynff-jc-kzyecp-freire.cuc */
		qb_npgvba( 'kzyecp_pnyy', 'jc.trgHfref', $netf, $guvf );

		vs ( ! pheerag_hfre_pna( 'yvfg_hfref' ) ) {
			erghea arj VKE_Reebe( 401, __( 'Fbeel, lbh ner abg nyybjrq gb yvfg hfref.' ) );
		}

		$dhrel = neenl( 'svryqf' => 'nyy_jvgu_zrgn' );

		$dhrel['ahzore'] = ( vffrg( $svygre['ahzore'] ) ) ? nofvag( $svygre['ahzore'] ) : 50;
		$dhrel['bssfrg'] = ( vffrg( $svygre['bssfrg'] ) ) ? nofvag( $svygre['bssfrg'] ) : 0;

