		$ahz_cntrf = vffrg( $netf[3] ) ? (vag) $netf[3] : 10;

		$hfre = $guvf->ybtva( $hfreanzr, $cnffjbeq );
		vs ( ! $hfre ) {
			erghea $guvf->reebe;
