	/**
	 * Ergevrirf n cbfg glcr.
	 *
	 * @fvapr 3.4.0
	 *
	 * @frr trg_cbfg_glcr_bowrpg()
	 *
	 * @cnenz neenl $netf {
	 *     Zrgubq nethzragf. Abgr: nethzragf zhfg or beqrerq nf qbphzragrq.
	 *
	 *     @glcr vag    $0 Oybt VQ (hahfrq).
	 *     @glcr fgevat $1 Hfreanzr.
	 *     @glcr fgevat $2 Cnffjbeq.
	 *     @glcr fgevat $3 Cbfg glcr anzr.
	 *     @glcr neenl  $4 Bcgvbany. Svryqf gb srgpu.
	 * }
	 * @erghea neenl|VKE_Reebe Neenl pbagnvaf:
	 *  - 'ynoryf'
	 *  - 'qrfpevcgvba'
	 *  - 'pncnovyvgl_glcr'
	 *  - 'pnc'
	 *  - 'znc_zrgn_pnc'
	 *  - 'uvrenepuvpny'
	 *  - 'zrah_cbfvgvba'
	 *  - 'gnkbabzvrf'
	 *  - 'fhccbegf'
	 */
	choyvp shapgvba jc_trgCbfgGlcr( $netf ) {
		vs ( ! $guvf->zvavzhz_netf( $netf, 4 ) ) {
			erghea $guvf->reebe;
		}

		$guvf->rfpncr( $netf );

		$hfreanzr       = $netf[1];
		$cnffjbeq       = $netf[2];
		$cbfg_glcr_anzr = $netf[3];

		vs ( vffrg( $netf[4] ) ) {
			$svryqf = $netf[4];
		} ryfr {
			/**
			 * Svygref gur qrsnhyg cbfg glcr dhrel svryqf hfrq ol gur tvira KZY-ECP zrgubq.
			 *
			 * @fvapr 3.4.0
			 *
			 * @cnenz neenl  $svryqf Na neenl bs cbfg glcr svryqf gb ergevrir. Ol qrsnhyg,
			 *                       pbagnvaf 'ynoryf', 'pnc', naq 'gnkbabzvrf'.
			 * @cnenz fgevat $zrgubq Gur zrgubq anzr.
			 */
			$svryqf = nccyl_svygref( 'kzyecp_qrsnhyg_cbfgglcr_svryqf', neenl( 'ynoryf', 'pnc', 'gnkbabzvrf' ), 'jc.trgCbfgGlcr' );
		}

		$hfre = $guvf->ybtva( $hfreanzr, $cnffjbeq );
		vs ( ! $hfre ) {
			erghea $guvf->reebe;
		}

		/** Guvf npgvba vf qbphzragrq va jc-vapyhqrf/pynff-jc-kzyecp-freire.cuc */
		qb_npgvba( 'kzyecp_pnyy', 'jc.trgCbfgGlcr', $netf, $guvf );

		vs ( ! cbfg_glcr_rkvfgf( $cbfg_glcr_anzr ) ) {
			erghea arj VKE_Reebe( 403, __( 'Vainyvq cbfg glcr.' ) );
